const fs = require('fs');
const REGISTRY_PATH = '/data/shared/templates/registry.json';
const TEMPLATES_DIR = '/data/shared/templates';

// Een read op deze bind-mount kan met EIO falen. De gemeten oorzaak: het
// projekt staat in ~/Documents en dus in iCloud Drive. Haalt macOS een bestand
// weg om ruimte te maken, dan blijft er een 'dataless' placeholder achter —
// de host haalt hem bij lezen stilzwijgend terug, maar een container krijgt
// over de mount alleen EIO. Dat is dus NIET transient: retries lossen het niet
// op zolang het bestand niet lokaal staat. Ze vangen wel de echte hikjes af;
// het vangnet dat telt is de cache van de laatste geslaagde uitlezing.
const TRANSIENT = ['EIO', 'EBUSY', 'EAGAIN', 'ESTALE', 'ENOENT'];
const MAX_ATTEMPTS = 4;

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

// openSync/readSync forceert een nieuwe fd; readFileSync kan op VirtioFS op
// een stale handle blijven hangen en steeds dezelfde EIO teruggeven.
function readFileFresh(filePath) {
  const fd = fs.openSync(filePath, 'r');
  try {
    const size = fs.fstatSync(fd).size;
    const buf = Buffer.alloc(size);
    let offset = 0;
    while (offset < size) {
      const read = fs.readSync(fd, buf, offset, size - offset, offset);
      if (read <= 0) break;
      offset += read;
    }
    return buf.subarray(0, offset).toString('utf8');
  } finally {
    fs.closeSync(fd);
  }
}

async function readRegistry() {
  let lastErr;
  for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {
    try {
      return JSON.parse(readFileFresh(REGISTRY_PATH));
    } catch (err) {
      lastErr = err;
      // Een JSON-parsefout is niet transient — direct stoppen.
      if (!err.code || !TRANSIENT.includes(err.code)) break;
      await sleep(attempt * 150);
    }
  }
  throw lastErr;
}

function statSafe(filePath) {
  for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {
    try {
      return fs.statSync(filePath);
    } catch (err) {
      if (!err.code || !TRANSIENT.includes(err.code)) return null;
    }
  }
  return null;
}

const staticData = $getWorkflowStaticData('global');

let registry;
try {
  registry = await readRegistry();
} catch (err) {
  const cache = staticData.templatesCache;
  if (cache && Array.isArray(cache.banks)) {
    // Laatste geslaagde uitlezing serveren, zodat de Templates-pagina blijft
    // werken zolang het bestand zelf niet te lezen is.
    return [{
      json: {
        success: true,
        stale: true,
        warning:
          `Registry kon nu niet gelezen worden (${err.code || 'fout'}: ${err.message}); ` +
          `gegevens van ${cache.cached_at} worden getoond. ` +
          `Bij EIO staat het bestand vermoedelijk niet lokaal maar in iCloud; ` +
          `open het één keer op de host of houd de projectmap gedownload.`,
        schema_version: cache.schema_version,
        banks: cache.banks,
      },
    }];
  }
  const hint = err.code === 'EIO'
    ? ' EIO op deze mount betekent bijna altijd dat macOS het bestand naar iCloud heeft weggeschreven ' +
      '(dataless placeholder). Open het bestand één keer op de host, of houd de projectmap lokaal ' +
      '(Finder: Nu downloaden / Gedownload houden). Een herstart van n8n helpt hier niet.'
    : '';
  return [{
    json: {
      success: false,
      error: `Kon registry niet lezen na ${MAX_ATTEMPTS} pogingen: ${err.message}.${hint}`,
      banks: [],
    },
  }];
}

const banks = Object.entries(registry.banks || {}).map(([bankId, b]) => {
  const templateFilename = b.template_filename || null;
  const templatePath = templateFilename
    ? `${TEMPLATES_DIR}/${bankId}/${templateFilename}`
    : null;
  const stat = templatePath ? statSafe(templatePath) : null;
  return {
    bank_id: bankId,
    display_name: b.display_name || bankId,
    keywords: b.keywords || [],
    template_filename: templateFilename,
    uploaded_at: b.uploaded_at || null,
    uploaded_by: b.uploaded_by || null,
    file_exists: Boolean(stat),
    file_size: stat ? stat.size : null,
    file_mtime: stat ? stat.mtime.toISOString() : null,
    placeholder_count: Object.keys(b.placeholders || {}).length,
  };
});

const schemaVersion = registry.schema_version || 1;
staticData.templatesCache = {
  schema_version: schemaVersion,
  banks,
  cached_at: new Date().toISOString(),
};

return [{
  json: {
    success: true,
    schema_version: schemaVersion,
    banks,
  },
}];

