// Verwacht multipart-form-data: bank_id (text field) + file (binary, .docx)
const body = $json.body || $json || {};
const bankId = String(body.bank_id || '').trim();
const uploadedBy = String(body.uploaded_by || 'webapp').trim() || 'webapp';

if (!bankId) {
  throw new Error('Veld \'bank_id\' ontbreekt in form data.');
}
if (!/^[a-z0-9_-]+$/i.test(bankId)) {
  throw new Error(`Ongeldig bank_id: '${bankId}'. Alleen letters/cijfers/-/_ toegestaan.`);
}

const binaries = $binary || {};
const binKeys = Object.keys(binaries);
let binKey = ['file', 'template'].find((k) => binaries[k])
  || (binKeys.length === 1 ? binKeys[0] : null);
if (!binKey) {
  binKey = binKeys.find((k) =>
    String(binaries[k]?.fileName || '').toLowerCase().endsWith('.docx')
  ) || null;
}
if (!binKey) {
  throw new Error(
    `Geen .docx-bestand gevonden in upload. Binary keys: ${binKeys.join(', ') || '(geen)'}.`
  );
}
const binEntry = binaries[binKey];

const originalName = String(binEntry.fileName || 'template.docx');
if (!originalName.toLowerCase().endsWith('.docx')) {
  throw new Error(`Alleen .docx-bestanden zijn toegestaan. Ontvangen: ${originalName}`);
}

// Sanitize filename — voorkom path traversal.
const safeName = path.basename(originalName).replace(/[^A-Za-z0-9._-]/g, '_');
if (!safeName.toLowerCase().endsWith('.docx')) {
  throw new Error(`Bestandsnaam niet bruikbaar na sanitization: '${safeName}'`);
}

// Lees registry, valideer bank.
let registry;
try {
  registry = await readRegistry();
} catch (err) {
  const hint = err.code === 'EIO'
    ? ' EIO op deze mount betekent bijna altijd dat macOS het bestand naar iCloud heeft weggeschreven; '
      + 'open het één keer op de host of houd de projectmap lokaal gedownload.'
    : '';
  throw new Error(`Kon registry niet lezen na ${MAX_ATTEMPTS} pogingen: ${err.message}.${hint}`);
}
const banks = registry.banks || {};
if (!banks[bankId]) {
  const known = Object.keys(banks).join(', ') || '(geen)';
  throw new Error(
    `Bank '${bankId}' is niet bekend in registry.json. ` +
    `Bekende banken: ${known}. Vraag een ontwikkelaar deze toe te voegen.`
  );
}

// n8n 2.x geeft via $binary alleen metadata; de inhoud staat los opgeslagen
// (filesystem- of database-modus) en komt via de helper binnen. Zie ook de
// transcript-bijlage in bespreking-workflow.json, die dezelfde weg gaat.
let buffer;
if (typeof this?.helpers?.getBinaryDataBuffer === 'function') {
  buffer = await this.helpers.getBinaryDataBuffer(0, binKey);
} else if (binEntry.data) {
  buffer = Buffer.from(binEntry.data, 'base64');
} else {
  throw new Error('Kon de inhoud van het geuploade bestand niet lezen.');
}
if (!buffer || !buffer.length) {
  throw new Error('Het geuploade bestand is leeg.');
}

// Schrijf het bestand.
const targetDir = path.join(TEMPLATES_DIR, bankId);
fs.mkdirSync(targetDir, { recursive: true });
const targetPath = path.join(targetDir, safeName);
await writeFileAtomic(targetPath, buffer);

// Update registry.
const now = new Date().toISOString();
banks[bankId].template_filename = safeName;
banks[bankId].uploaded_at = now;
banks[bankId].uploaded_by = uploadedBy;
await writeFileAtomic(REGISTRY_PATH, JSON.stringify(registry, null, 2) + '\n');

// Houd de fallback-cache van 'Read Registry' in de pas, zodat een GET die
// direct hierna op een mount-hik stuit niet de oude bestandsnaam toont.
const staticData = $getWorkflowStaticData('global');
const cached = staticData.templatesCache;
if (cached && Array.isArray(cached.banks)) {
  const entry = cached.banks.find((b) => b.bank_id === bankId);
  if (entry) {
    Object.assign(entry, {
      template_filename: safeName,
      uploaded_at: now,
      uploaded_by: uploadedBy,
      file_exists: true,
      file_size: buffer.length,
      file_mtime: now,
    });
    cached.cached_at = now;
  }
}

return [{
  json: {
    success: true,
    bank_id: bankId,
    display_name: banks[bankId].display_name || bankId,
    template_filename: safeName,
    template_path: targetPath,
    file_size: buffer.length,
    uploaded_at: now,
    uploaded_by: uploadedBy,
  },
}];

