// ---------------------------------------------------------------------------
// Overzicht van de bespreeksjablonen in shared/templates/besprekingen/.
//
// Anders dan de banktemplates is hier geen registry: de map ís de bron. Elk
// .json-bestand is één soort bespreking, en bespreking-workflow.json leest die
// bestanden rechtstreeks — voor de soort-herkenning, de blok-samenvatting, de
// verslagprompt en het ordenen van de secties. Dit endpoint levert de volledige
// inhoud mee, zodat de editor in de webapp geen tweede aanroep nodig heeft.
// ---------------------------------------------------------------------------

// 'auto' en 'algemeen' betekenen in de workflow juist 'geen sjabloon'; ze mogen
// dus nooit de naam van een sjabloonbestand worden.
const GERESERVEERD = ['auto', 'algemeen'];

function versiesVan(soort) {
  const dir = `${VERSIE_DIR}/${soort}`;
  return readdirSafe(dir)
    .filter((naam) => naam.endsWith('.json'))
    .map((naam) => {
      const stat = statSafe(`${dir}/${naam}`);
      return {
        versie_id: naam.replace(/\.json$/, ''),
        opgeslagen_op: stat ? stat.mtime.toISOString() : null,
        grootte: stat ? stat.size : null,
      };
    })
    .sort((a, b) => String(b.versie_id).localeCompare(String(a.versie_id)));
}

const bestanden = readdirSafe(SJABLOON_DIR).filter((naam) => naam.endsWith('.json'));

const sjablonen = [];
const onleesbaar = [];

for (const bestand of bestanden) {
  const pad = `${SJABLOON_DIR}/${bestand}`;
  let sjabloon;
  try {
    sjabloon = JSON.parse(await readTextResilient(pad));
  } catch (err) {
    onleesbaar.push({ bestand, fout: err.message });
    continue;
  }

  const soort = String(sjabloon.soort || bestand.replace(/\.json$/, ''));
  const stat = statSafe(pad);

  // Het bespreekformulier waar het sjabloon van is afgeleid. Wordt door de
  // workflow niet gelezen — het staat erbij zodat je de kopjes naast het
  // origineel kunt leggen.
  const bron = sjabloon.bron ? String(sjabloon.bron) : null;
  const bronStat = bron ? statSafe(`${SJABLOON_DIR}/${bron}`) : null;

  sjablonen.push({
    soort,
    naam: sjabloon.naam || soort,
    bestand,
    toelichting: sjabloon.toelichting || '',
    herken_op: Array.isArray(sjabloon.herken_op) ? sjabloon.herken_op.map(String) : [],
    secties: (Array.isArray(sjabloon.secties) ? sjabloon.secties : []).map((sec) => ({
      kop: String(sec.kop || ''),
      aanwijzing: String(sec.aanwijzing || ''),
      trefwoorden: Array.isArray(sec.trefwoorden) ? sec.trefwoorden.map(String) : [],
      altijd_nacontrole: Boolean(sec.altijd_nacontrole),
    })),
    bron,
    bron_bestaat: Boolean(bronStat),
    bron_grootte: bronStat ? bronStat.size : null,
    gewijzigd_op: stat ? stat.mtime.toISOString() : null,
    versies: versiesVan(soort),
  });
}

sjablonen.sort((a, b) => a.naam.localeCompare(b.naam, 'nl'));

// Soorten waarvan alleen nog versiehistorie over is: verwijderd, maar met
// 'herstellen' terug te halen. Zonder dit zou een verwijderd sjabloon spoorloos
// lijken terwijl het gewoon nog op schijf staat.
const actief = new Set(sjablonen.map((s) => s.soort));
const verwijderd = readdirSafe(VERSIE_DIR)
  .filter((soort) => !actief.has(soort) && versiesVan(soort).length)
  .map((soort) => ({ soort, versies: versiesVan(soort) }))
  .sort((a, b) => a.soort.localeCompare(b.soort, 'nl'));

return [{
  json: {
    success: true,
    sjablonen,
    verwijderd,
    gereserveerde_soorten: GERESERVEERD,
    // Bestanden die er wel staan maar niet te parsen zijn. Niet stilzwijgend
    // weglaten: dan lijkt een sjabloon spoorloos terwijl het er gewoon staat.
    onleesbaar,
  },
}];

