if (actie !== 'opslaan') {
  return mislukt(
    `Onbekende actie: '${actie}'. Verwacht 'opslaan', 'herstellen' of 'verwijderen'.`
  );
}

const sjabloon = payload.sjabloon || {};
const fouten = [];

const soort = String(sjabloon.soort || '').trim().toLowerCase();
if (!SOORT_PATROON.test(soort)) {
  // Letters-only is geen willekeur: bespreking-workflow.json normaliseert de
  // soort met /[^a-z]/gi voordat het het bestand zoekt. Een soort met een cijfer
  // of streepje zou daar stilzwijgend niet gevonden worden.
  fouten.push(
    `Soort '${sjabloon.soort || ''}' is ongeldig: gebruik 2 tot 40 kleine letters ` +
    `zonder spaties, cijfers of leestekens (bijvoorbeeld 'schenking').`
  );
} else if (GERESERVEERD.includes(soort)) {
  fouten.push(`Soort '${soort}' is gereserveerd: dat betekent in de workflow juist 'geen vaste indeling'.`);
}

const naam = String(sjabloon.naam || '').trim();
if (!naam) fouten.push('Naam is verplicht.');
if (naam.length > 80) fouten.push('Naam mag hoogstens 80 tekens zijn.');

const toelichting = String(sjabloon.toelichting || '').trim();
if (toelichting.length > 4000) fouten.push('Toelichting mag hoogstens 4000 tekens zijn.');

const herkenOp = (Array.isArray(sjabloon.herken_op) ? sjabloon.herken_op : [])
  .map((w) => String(w).trim().toLowerCase())
  .filter(Boolean);
if (herkenOp.length > 30) fouten.push('Hoogstens 30 herkenwoorden.');
if (new Set(herkenOp).size !== herkenOp.length) fouten.push('Herkenwoorden bevatten dubbelen.');

const secties = Array.isArray(sjabloon.secties) ? sjabloon.secties : [];
if (!secties.length) fouten.push('Een sjabloon heeft minstens één sectie nodig.');
if (secties.length > 60) fouten.push('Hoogstens 60 secties.');

const gezien = new Set();
const schoneSecties = secties.map((sec, i) => {
  const kop = String(sec.kop || '').trim();
  const nr = i + 1;
  if (!kop) {
    fouten.push(`Sectie ${nr} heeft geen kop.`);
  } else if (kop.length > 100) {
    fouten.push(`Kop van sectie ${nr} mag hoogstens 100 tekens zijn.`);
  } else {
    // Dubbele kopjes zijn funest: 'Orden Secties' verdeelt de punten op
    // koptekst, dus bij twee gelijke kopjes belandt alles onder de eerste.
    const sleutel = kop.toLowerCase();
    if (gezien.has(sleutel)) fouten.push(`Kop '${kop}' komt meer dan één keer voor.`);
    gezien.add(sleutel);
  }

  const aanwijzing = String(sec.aanwijzing || '').trim();
  if (aanwijzing.length > 4000) fouten.push(`Aanwijzing van '${kop || nr}' mag hoogstens 4000 tekens zijn.`);

  const trefwoorden = (Array.isArray(sec.trefwoorden) ? sec.trefwoorden : [])
    .map((w) => String(w).trim().toLowerCase())
    .filter(Boolean);
  if (trefwoorden.length > 100) fouten.push(`Sectie '${kop || nr}' heeft meer dan 100 trefwoorden.`);

  const schoon = { kop, aanwijzing, trefwoorden: [...new Set(trefwoorden)] };
  if (sec.altijd_nacontrole) schoon.altijd_nacontrole = true;
  return schoon;
});

// Bron-.docx: alleen een bestandsnaam binnen de sjabloonmap, nooit een pad.
let bron = null;
if (sjabloon.bron) {
  const kaal = path.basename(String(sjabloon.bron));
  if (!kaal.toLowerCase().endsWith('.docx')) {
    fouten.push(`Bron '${kaal}' is geen .docx-bestand.`);
  } else {
    bron = kaal;
  }
}

if (fouten.length) {
  return [{ json: { success: false, error: fouten.join(' '), fouten } }];
}

const bestaatAl = Boolean(statSafe(bestandVan(soort)));
if (payload.nieuw && bestaatAl) {
  return [{
    json: {
      success: false,
      error: `Er bestaat al een sjabloon met soort '${soort}'. Kies een andere soort of bewerk het bestaande.`,
    },
  }];
}

// Veldvolgorde gelijk houden aan de bestaande bestanden, zodat een diff in git
// leesbaar blijft en niet elk veld van plek verspringt.
const uit = { soort, naam };
if (bron) uit.bron = bron;
uit.herken_op = herkenOp;
if (toelichting) uit.toelichting = toelichting;
uit.secties = schoneSecties;

const bewaard = await bewaarVersie(soort);
fs.mkdirSync(SJABLOON_DIR, { recursive: true });
await writeFileAtomic(bestandVan(soort), JSON.stringify(uit, null, 2) + '\n');

return [{
  json: {
    success: true,
    actie: 'opslaan',
    soort,
    naam,
    nieuw: !bestaatAl,
    secties_aantal: schoneSecties.length,
    vorige_versie_bewaard_als: bewaard,
    // Geen blokkerende fout, wel het melden waard: zonder aanwijzing krijgt het
    // model niets mee over wat er onder het kopje hoort.
    waarschuwingen: schoneSecties
      .filter((s) => !s.aanwijzing)
      .map((s) => `Sectie '${s.kop}' heeft geen aanwijzing; het model krijgt dan alleen de kop als houvast.`),
  },
}];

const fs = require('fs');
const path = require('path');
const SJABLOON_DIR = '/data/shared/templates/besprekingen';
const VERSIE_DIR = `${SJABLOON_DIR}/.versies`;
const MAX_VERSIES = 20;

// De map ligt op een Docker bind-mount naar de host. Zie 'Read Registry' voor
// de achtergrond: een EIO hier betekent meestal dat macOS het bestand naar
// iCloud heeft weggeschreven. Lezen en schrijven gaan daarom met retries, en
// schrijven atomair.
const TRANSIENT = ['EIO', 'EBUSY', 'EAGAIN', 'ESTALE', 'ENOENT'];
const MAX_ATTEMPTS = 4;

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function readFileFresh(filePath) {
  const fd = fs.openSync(filePath, 'r');
  try {
    const size = fs.fstatSync(fd).size;
    const buf = Buffer.alloc(size);
    let offset = 0;
    while (offset < size) {
      const read = fs.readSync(fd, buf, offset, size - offset, offset);
      if (read <= 0) break;
      offset += read;
    }
    return buf.subarray(0, offset).toString('utf8');
  } finally {
    fs.closeSync(fd);
  }
}

async function readTextResilient(filePath) {
  let lastErr;
  for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {
    try {
      return readFileFresh(filePath);
    } catch (err) {
      lastErr = err;
      if (!err.code || !TRANSIENT.includes(err.code)) break;
      await sleep(attempt * 150);
    }
  }
  throw lastErr;
}

async function writeFileAtomic(target, data) {
  let lastErr;
  for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {
    const tmp = `${target}.tmp-${Date.now()}-${attempt}`;
    try {
      fs.writeFileSync(tmp, data);
      fs.renameSync(tmp, target);
      return;
    } catch (err) {
      lastErr = err;
      try { fs.unlinkSync(tmp); } catch { /* tmp bestond al niet */ }
      if (!err.code || !TRANSIENT.includes(err.code)) break;
      await sleep(attempt * 150);
    }
  }
  throw lastErr;
}

function readdirSafe(dir) {
  try {
    return fs.readdirSync(dir);
  } catch {
    return [];
  }
}

function statSafe(filePath) {
  for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {
    try {
      return fs.statSync(filePath);
    } catch (err) {
      if (!err.code || !TRANSIENT.includes(err.code)) return null;
    }
  }
  return null;
}

// ---------------------------------------------------------------------------
// Uploaden van het papieren bespreekformulier waar een sjabloon van is afgeleid.
//
// De workflow doet niets met dit bestand — het staat er zodat de behandelaar de
// kopjes in de editor naast het origineel kan leggen. Het sjabloon verwijst
// ernaar met het veld 'bron'; dat wordt hier meteen bijgewerkt.
// ---------------------------------------------------------------------------

const SOORT_PATROON = /^[a-z]{2,40}$/;

// Verwachte fouten als data terug, niet als throw: een throw in een Code node
// levert bij responseMode=responseNode een leeg 200-antwoord op.
function mislukt(bericht) {
  return [{ json: { success: false, error: bericht } }];
}

const body = $json.body || $json || {};
const soort = String(body.soort || '').trim().toLowerCase();
if (!SOORT_PATROON.test(soort)) {
  return mislukt(`Ongeldige soort: '${body.soort || ''}'.`);
}

const sjabloonPad = `${SJABLOON_DIR}/${soort}.json`;
if (!statSafe(sjabloonPad)) {
  return mislukt(`Sjabloon '${soort}' bestaat niet; sla het eerst op.`);
}

const binaries = $binary || {};
const binKeys = Object.keys(binaries);
let binKey = binaries.file ? 'file' : (binKeys.length === 1 ? binKeys[0] : null);
if (!binKey) {
  binKey = binKeys.find((k) =>
    String(binaries[k]?.fileName || '').toLowerCase().endsWith('.docx')
  ) || null;
}
if (!binKey) {
  return mislukt(`Geen .docx-bestand gevonden in upload. Binary keys: ${binKeys.join(', ') || '(geen)'}.`);
}
const binEntry = binaries[binKey];

const originalName = String(binEntry.fileName || 'bespreekformulier.docx');
if (!originalName.toLowerCase().endsWith('.docx')) {
  return mislukt(`Alleen .docx-bestanden zijn toegestaan. Ontvangen: ${originalName}`);
}

// Sanitize — voorkom path traversal.
const safeName = path.basename(originalName).replace(/[^A-Za-z0-9._ -]/g, '_').trim();
if (!safeName.toLowerCase().endsWith('.docx')) {
  return mislukt(`Bestandsnaam niet bruikbaar na sanitization: '${safeName}'`);
}

// n8n 2.x geeft via $binary alleen metadata; de inhoud staat los opgeslagen
// (filesystem- of database-modus) en komt via de helper binnen. Zie ook de
// transcript-bijlage in bespreking-workflow.json, die dezelfde weg gaat.
let buffer;
if (typeof this?.helpers?.getBinaryDataBuffer === 'function') {
  buffer = await this.helpers.getBinaryDataBuffer(0, binKey);
} else if (binEntry.data) {
  buffer = Buffer.from(binEntry.data, 'base64');
} else {
  return mislukt('Kon de inhoud van het geuploade bestand niet lezen.');
}
if (!buffer || !buffer.length) {
  return mislukt('Het geuploade bestand is leeg.');
}

await writeFileAtomic(`${SJABLOON_DIR}/${safeName}`, buffer);

// Sjabloon naar het nieuwe bestand laten wijzen. De oude bron blijft staan:
// hij kan bij een ander sjabloon in gebruik zijn, en weggooien van een
// brondocument is niets voor een zijeffect van een upload.
const sjabloon = JSON.parse(await readTextResilient(sjabloonPad));
const vorigeBron = sjabloon.bron || null;
sjabloon.bron = safeName;
await writeFileAtomic(sjabloonPad, JSON.stringify(sjabloon, null, 2) + '\n');

return [{
  json: {
    success: true,
    soort,
    bron: safeName,
    vorige_bron: vorigeBron,
    file_size: buffer.length,
  },
}];

