// Placeholders die de generator zelf invult uit kantoor.json en de
// cliëntgegevens; die hoeven niet als invulveld op een blok te staan.
const SYSTEEM_PLACEHOLDERS = [
  '<<AKTE_DATUM>>',
  '<<NOTARIS_NAAM>>',
  '<<NOTARIS_STANDPLAATS>>',
  '<<ERFLATERS>>',
  '<<SLOT_TEKST>>',
];

function placeholdersIn(tekst) {
  return String(tekst || '').match(/<<[A-Z0-9_]+>>/g) || [];
}

// ---------------------------------------------------------------------------
// Overzicht van de akteblokken in shared/templates/aktes/.
//
// Eén .json-bestand per aktesoort. Elk blok hangt via `kop` aan een kopje uit
// het bijbehorende bespreeksjabloon; kwam er in de bespreking inhoud onder dat
// kopje, dan stelt de bouwer het blok voor. `kop: null` met `altijd: true` zijn
// de vaste blokken (aanhef, slotformule) die er altijd in gaan.
//
// De volledige inhoud gaat mee, zodat zowel de editor als de testament-bouwer
// aan één aanroep genoeg heeft. Bedragen blijven in centen; de webapp rekent ze
// om naar euro's.
// ---------------------------------------------------------------------------

const BESPREKING_DIR = '/data/shared/templates/besprekingen';

function versiesVan(soort) {
  const dir = `${VERSIE_DIR}/${soort}`;
  return readdirSafe(dir)
    .filter((naam) => naam.endsWith('.json'))
    .map((naam) => {
      const stat = statSafe(`${dir}/${naam}`);
      return {
        versie_id: naam.replace(/\.json$/, ''),
        opgeslagen_op: stat ? stat.mtime.toISOString() : null,
        grootte: stat ? stat.size : null,
      };
    })
    .sort((a, b) => String(b.versie_id).localeCompare(String(a.versie_id)));
}

function centen(waarde) {
  const n = Math.round(Number(waarde));
  return Number.isFinite(n) && n >= 0 ? n : 0;
}

// De koppen van het gekoppelde bespreeksjabloon. Nodig voor de kruiscontrole
// hieronder: hernoemt iemand een kopje in het bespreeksjabloon, dan wordt het
// bijbehorende akteblok stilzwijgend nooit meer voorgesteld. Dat moet zichtbaar
// zijn in het beheerscherm, niet pas als er een clausule ontbreekt in een akte.
async function koppenVan(sjabloonSoort) {
  if (!sjabloonSoort || !/^[a-z]{2,40}$/.test(sjabloonSoort)) return [];
  try {
    const sj = JSON.parse(await readTextResilient(`${BESPREKING_DIR}/${sjabloonSoort}.json`));
    return (Array.isArray(sj.secties) ? sj.secties : []).map((s) => String(s.kop || ''));
  } catch {
    return [];
  }
}

const bestanden = readdirSafe(AKTE_DIR).filter((naam) => naam.endsWith('.json'));

const aktes = [];
const onleesbaar = [];

for (const bestand of bestanden) {
  const pad = `${AKTE_DIR}/${bestand}`;
  let bron;
  try {
    bron = JSON.parse(await readTextResilient(pad));
  } catch (err) {
    onleesbaar.push({ bestand, fout: err.message });
    continue;
  }

  const soort = String(bron.soort || bestand.replace(/\.json$/, ''));
  const stat = statSafe(pad);
  const sjabloonSoort = bron.bespreeksjabloon ? String(bron.bespreeksjabloon) : null;
  const bekendeKoppen = await koppenVan(sjabloonSoort);
  const koppenSet = new Set(bekendeKoppen);

  const blokken = (Array.isArray(bron.blokken) ? bron.blokken : []).map((b) => {
    const velden = (Array.isArray(b.velden) ? b.velden : []).map((v) => ({
      naam: String(v.naam || ''),
      label: String(v.label || v.naam || ''),
      hint: String(v.hint || ''),
    }));
    // Een placeholder die nergens als invulveld staat en ook geen systeemveld
    // is, blijft in de akte letterlijk als <<TYPFOUT>> staan. Dat is stil en
    // vervelend, dus het overzicht meldt het. Andersom ook: een veld dat in de
    // tekst niet voorkomt, vraagt de gebruiker om iets in te vullen dat nergens
    // terechtkomt.
    const gedeclareerd = new Set([
      ...velden.map((v) => `<<${v.naam}>>`),
      ...SYSTEEM_PLACEHOLDERS,
    ]);
    const inTekst = [...new Set(placeholdersIn(b.tekst))];
    const kop = b.kop == null ? null : String(b.kop);
    return {
      id: String(b.id || ''),
      naam: String(b.naam || b.id || ''),
      kop,
      // null-kop is bewust losgekoppeld (aanhef, slot) en dus altijd in orde;
      // zonder bespreeksjabloon valt er niets te controleren.
      kop_bestaat: kop === null || !bekendeKoppen.length ? true : koppenSet.has(kop),
      altijd: Boolean(b.altijd),
      prijs_cent: centen(b.prijs_cent),
      tekst: String(b.tekst || ''),
      velden,
      onbekende_placeholders: inTekst.filter((p) => !gedeclareerd.has(p)),
      ongebruikte_velden: velden
        .map((v) => `<<${v.naam}>>`)
        .filter((p) => !inTekst.includes(p)),
    };
  });

  aktes.push({
    soort,
    naam: bron.naam || soort,
    bestand,
    bespreeksjabloon: sjabloonSoort,
    bekende_koppen: bekendeKoppen,
    basistarief_cent: centen(bron.basistarief_cent),
    tarief_tweede_testament_cent: centen(bron.tarief_tweede_testament_cent),
    verschotten: (Array.isArray(bron.verschotten) ? bron.verschotten : []).map((v) => ({
      naam: String(v.naam || ''),
      bedrag_cent: centen(v.bedrag_cent),
      per_testament: Boolean(v.per_testament),
    })),
    blokken,
    gewijzigd_op: stat ? stat.mtime.toISOString() : null,
    versies: versiesVan(soort),
  });
}

aktes.sort((a, b) => a.naam.localeCompare(b.naam, 'nl'));

// Soorten waarvan alleen nog versiehistorie over is: verwijderd, maar met
// 'herstellen' terug te halen.
const actief = new Set(aktes.map((a) => a.soort));
const verwijderd = readdirSafe(VERSIE_DIR)
  .filter((soort) => !actief.has(soort) && versiesVan(soort).length)
  .map((soort) => ({ soort, versies: versiesVan(soort) }))
  .sort((a, b) => a.soort.localeCompare(b.soort, 'nl'));

return [{
  json: {
    success: true,
    aktes,
    verwijderd,
    systeem_placeholders: SYSTEEM_PLACEHOLDERS,
    onleesbaar,
  },
}];

