async function readTextResilient(filePath) {
  let lastErr;
  for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {
    try {
      return readFileFresh(filePath);
    } catch (err) {
      lastErr = err;
      if (!err.code || !TRANSIENT.includes(err.code)) break;
      await sleep(attempt * 150);
    }
  }
  throw lastErr;
}

async function writeFileAtomic(target, data) {
  let lastErr;
  for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {
    const tmp = `${target}.tmp-${Date.now()}-${attempt}`;
    try {
      fs.writeFileSync(tmp, data);
      fs.renameSync(tmp, target);
      return;
    } catch (err) {
      lastErr = err;
      try { fs.unlinkSync(tmp); } catch { /* tmp bestond al niet */ }
      if (!err.code || !TRANSIENT.includes(err.code)) break;
      await sleep(attempt * 150);
    }
  }
  throw lastErr;
}

function readdirSafe(dir) {
  try {
    return fs.readdirSync(dir);
  } catch {
    return [];
  }
}

function statSafe(filePath) {
  for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {
    try {
      return fs.statSync(filePath);
    } catch (err) {
      if (!err.code || !TRANSIENT.includes(err.code)) return null;
    }
  }
  return null;
}

// Placeholders die de generator zelf invult uit kantoor.json en de
// cliëntgegevens; die hoeven niet als invulveld op een blok te staan.
const SYSTEEM_PLACEHOLDERS = [
  '<<AKTE_DATUM>>',
  '<<NOTARIS_NAAM>>',
  '<<NOTARIS_STANDPLAATS>>',
  '<<ERFLATERS>>',
  '<<SLOT_TEKST>>',
];

function placeholdersIn(tekst) {
  return String(tekst || '').match(/<<[A-Z0-9_]+>>/g) || [];
}

// ---------------------------------------------------------------------------
// Opslaan, aanmaken, verwijderen en terugdraaien van een akteblokken-bestand.
//
// Deze blokken vormen letterlijk de tekst van een concept-akte en bepalen de
// offerte. Een kapot bestand levert dus een onbruikbaar dossierstuk én een
// verkeerd bedrag op. Vandaar: strak valideren vóór het schrijven, atomair
// schrijven, en bij elke wijziging de vorige versie bewaren.
//
// Verwacht multipart-form-data met één veld 'payload' (JSON-tekst). Bewust
// geen application/json: dat lokt een CORS-preflight uit vanaf de webapp.
// ---------------------------------------------------------------------------

const SOORT_PATROON = /^[a-z]{2,40}$/;
const BLOK_ID_PATROON = /^[a-z0-9][a-z0-9-]{0,59}$/;
const VELD_PATROON = /^[A-Z][A-Z0-9_]{0,59}$/;

// Verwachte fouten komen als { success: false, error } terug, niet als throw:
// een throw in een Code node levert bij responseMode=responseNode een leeg
// 200-antwoord op, en daar kan de webapp geen zinnige melding van maken.
function mislukt(bericht, extra) {
  return [{ json: { success: false, error: bericht, ...(extra || {}) } }];
}

const body = $json.body || $json || {};
let payload;
try {
  payload = typeof body.payload === 'string' ? JSON.parse(body.payload) : (body.payload || body);
} catch (err) {
  return mislukt(`Kon payload niet lezen als JSON: ${err.message}`);
}

const actie = String(payload.actie || 'opslaan');

function bestandVan(soort) {
  return `${AKTE_DIR}/${soort}.json`;
}

async function bewaarVersie(soort) {
  const huidig = bestandVan(soort);
  if (!statSafe(huidig)) return null;

  let inhoud;
  try {
    inhoud = await readTextResilient(huidig);
  } catch {
    return null; // Niets te bewaren is geen reden om het opslaan te blokkeren.
  }

  const dir = `${VERSIE_DIR}/${soort}`;
  fs.mkdirSync(dir, { recursive: true });
  const versieId = new Date().toISOString().replace(/[:.]/g, '-');
  await writeFileAtomic(`${dir}/${versieId}.json`, inhoud);

  const oud = readdirSafe(dir)
    .filter((n) => n.endsWith('.json'))
    .sort()
    .slice(0, -MAX_VERSIES);
  for (const naam of oud) {
    try { fs.unlinkSync(`${dir}/${naam}`); } catch { /* best effort */ }
  }
  return versieId;
}

// --- Terugdraaien naar een eerdere versie -----------------------------------
if (actie === 'herstellen') {
  const soort = String(payload.soort || '').trim().toLowerCase();
  const versieId = String(payload.versie_id || '').trim();
  if (!SOORT_PATROON.test(soort)) {
    return mislukt(`Ongeldige soort: '${payload.soort || ''}'.`);
  }
  if (!/^[0-9A-Za-z_-]+$/.test(versieId)) {
    return mislukt(`Ongeldig versie_id: '${versieId}'.`);
  }
  const versiePad = `${VERSIE_DIR}/${soort}/${versieId}.json`;
  if (!statSafe(versiePad)) {
    return mislukt(`Versie '${versieId}' van aktesoort '${soort}' bestaat niet.`);
  }

  const inhoud = await readTextResilient(versiePad);
  JSON.parse(inhoud); // Nooit iets terugzetten dat zelf stuk is.
  const bewaard = await bewaarVersie(soort);
  fs.mkdirSync(AKTE_DIR, { recursive: true });
  await writeFileAtomic(bestandVan(soort), inhoud);

  return [{
    json: {
      success: true,
      actie: 'herstellen',
      soort,
      hersteld_naar: versieId,
      vorige_versie_bewaard_als: bewaard,
    },
  }];
}

// --- Verwijderen ------------------------------------------------------------
if (actie === 'verwijderen') {
  const soort = String(payload.soort || '').trim().toLowerCase();
  if (!SOORT_PATROON.test(soort)) {
    return mislukt(`Ongeldige soort: '${payload.soort || ''}'.`);
  }
  const pad = bestandVan(soort);
  if (!statSafe(pad)) {
    return mislukt(`Aktesoort '${soort}' bestaat niet (meer).`);
  }
  const bewaard = await bewaarVersie(soort);
  if (!bewaard) {
    return mislukt(
      `Kon '${soort}' niet veiligstellen in de versiehistorie; daarom niet verwijderd.`
    );
  }
  fs.unlinkSync(pad);

  return [{ json: { success: true, actie: 'verwijderen', soort, bewaard_als: bewaard } }];
}

// --- Opslaan (nieuw of gewijzigd) -------------------------------------------
if (actie !== 'opslaan') {
  return mislukt(
    `Onbekende actie: '${actie}'. Verwacht 'opslaan', 'herstellen' of 'verwijderen'.`
  );
}

const akte = payload.akte || {};
const fouten = [];

// Bedragen komen en gaan in hele centen. Optellen van euro's als kommagetallen
// geeft 562.0000000001, en bij 21% BTW wordt dat zichtbaar op de offerte.
function centen(waarde, naam, standaard) {
  if (waarde === undefined || waarde === null || waarde === '') return standaard;
  const n = Number(waarde);
  if (!Number.isFinite(n) || n < 0) {
    fouten.push(`${naam} moet een bedrag van 0 of hoger zijn (kreeg '${waarde}').`);
    return standaard;
  }
  if (!Number.isInteger(n)) {
    fouten.push(`${naam} moet een heel aantal centen zijn (kreeg '${waarde}').`);
    return standaard;
  }
  if (n > 100000000) {
    fouten.push(`${naam} is onwaarschijnlijk hoog (meer dan een miljoen euro).`);
    return standaard;
  }
  return n;
}

const soort = String(akte.soort || '').trim().toLowerCase();
if (!SOORT_PATROON.test(soort)) {
  fouten.push(
    `Soort '${akte.soort || ''}' is ongeldig: gebruik 2 tot 40 kleine letters zonder ` +
    `spaties, cijfers of leestekens (bijvoorbeeld 'testament').`
  );
}

const naam = String(akte.naam || '').trim();
if (!naam) fouten.push('Naam is verplicht.');
if (naam.length > 80) fouten.push('Naam mag hoogstens 80 tekens zijn.');

const basistarief = centen(akte.basistarief_cent, 'Basistarief', 0);
const tariefTweede = centen(akte.tarief_tweede_testament_cent, 'Tarief tweede testament', 0);

const verschotten = (Array.isArray(akte.verschotten) ? akte.verschotten : []).map((v, i) => {
  const vNaam = String(v.naam || '').trim();
  if (!vNaam) fouten.push(`Verschot ${i + 1} heeft geen omschrijving.`);
  return {
    naam: vNaam,
    bedrag_cent: centen(v.bedrag_cent, `Bedrag van verschot '${vNaam || i + 1}'`, 0),
    per_testament: Boolean(v.per_testament),
  };
});

const blokken = Array.isArray(akte.blokken) ? akte.blokken : [];
if (!blokken.length) fouten.push('Een aktesoort heeft minstens één blok nodig.');
if (blokken.length > 100) fouten.push('Hoogstens 100 blokken.');

const gezienId = new Set();
const schoneBlokken = blokken.map((b, i) => {
  const nr = i + 1;
  const id = String(b.id || '').trim().toLowerCase();
  if (!BLOK_ID_PATROON.test(id)) {
    fouten.push(
      `Blok ${nr} heeft een ongeldig id ('${b.id || ''}'): kleine letters, cijfers en ` +
      `koppeltekens, beginnend met een letter of cijfer.`
    );
  } else if (gezienId.has(id)) {
    // Dubbele id's maken het onmogelijk om een blok aan te vinken zonder ook
    // het andere te raken; de bouwer sleutelt erop.
    fouten.push(`Blok-id '${id}' komt meer dan één keer voor.`);
  } else {
    gezienId.add(id);
  }

  const bNaam = String(b.naam || '').trim();
  if (!bNaam) fouten.push(`Blok ${nr} heeft geen naam.`);
  // Een naamloos blok aanduiden als "blok '3'" leest verkeerd; dan liever het
  // volgnummer zonder aanhalingstekens.
  const label = bNaam ? `'${bNaam}'` : `${nr}`;

  const tekst = String(b.tekst || '').trim();
  if (!tekst) fouten.push(`Blok ${label} heeft geen tekst.`);
  if (tekst.length > 20000) fouten.push(`Tekst van blok ${label} is te lang.`);

  const gezienVeld = new Set();
  const velden = (Array.isArray(b.velden) ? b.velden : []).map((v, vi) => {
    const vNaam = String(v.naam || '').trim().toUpperCase();
    if (!VELD_PATROON.test(vNaam)) {
      fouten.push(
        `Veld ${vi + 1} van blok ${label} heeft een ongeldige naam ('${v.naam || ''}'): ` +
        `hoofdletters, cijfers en liggende streepjes, beginnend met een letter.`
      );
    } else if (gezienVeld.has(vNaam)) {
      fouten.push(`Veld '${vNaam}' komt meer dan één keer voor in blok ${label}.`);
    } else {
      gezienVeld.add(vNaam);
    }
    return {
      naam: vNaam,
      label: String(v.label || vNaam).trim(),
      hint: String(v.hint || '').trim(),
    };
  });

  return {
    id,
    naam: bNaam,
    kop: b.kop == null || String(b.kop).trim() === '' ? null : String(b.kop).trim(),
    altijd: Boolean(b.altijd),
    prijs_cent: centen(b.prijs_cent, `Prijs van blok ${label}`, 0),
    tekst,
    velden,
  };
});

if (fouten.length) {
  return mislukt(fouten.join(' '), { fouten });
}

const bestaatAl = Boolean(statSafe(bestandVan(soort)));
if (payload.nieuw && bestaatAl) {
  return mislukt(
    `Er bestaat al een aktesoort '${soort}'. Kies een andere soort of bewerk de bestaande.`
  );
}

// Twee schermen bewerken dit bestand: Akteblokken gaat over de tekst, het
// tarievenscherm over het geld. Zonder scheiding zou het opslaan van een
// tekstwijziging een tariefwijziging van een minuut eerder terugdraaien, want
// beide schermen sturen het hele object mee. `bereik` bepaalt daarom welk deel
// van de payload leidend is; de rest komt van schijf.
const bereik = String(payload.bereik || 'alles');
if (!['alles', 'blokken', 'tarieven'].includes(bereik)) {
  return mislukt(`Onbekend bereik: '${bereik}'. Verwacht 'blokken', 'tarieven' of 'alles'.`);
}

let huidig = null;
if (bestaatAl) {
  try {
    huidig = JSON.parse(await readTextResilient(bestandVan(soort)));
  } catch { /* niets over te nemen */ }
}
if (bereik !== 'alles' && !huidig) {
  return mislukt(
    `Aktesoort '${soort}' bestaat nog niet; een nieuwe soort moet in één keer worden aangemaakt.`
  );
}

let uitBasistarief = basistarief;
let uitTariefTweede = tariefTweede;
let uitVerschotten = verschotten;
let uitBlokken = schoneBlokken;

if (bereik === 'blokken') {
  // Tekst en structuur uit de payload, alle bedragen van schijf. Een nieuw blok
  // heeft daar nog geen prijs en begint dus op nul; dat is in het tarievenscherm
  // meteen zichtbaar.
  uitBasistarief = Number(huidig.basistarief_cent) || 0;
  uitTariefTweede = Number(huidig.tarief_tweede_testament_cent) || 0;
  uitVerschotten = Array.isArray(huidig.verschotten) ? huidig.verschotten : [];
  const prijzen = new Map(
    (Array.isArray(huidig.blokken) ? huidig.blokken : []).map((b) => [
      String(b.id),
      Number(b.prijs_cent) || 0,
    ])
  );
  uitBlokken = schoneBlokken.map((b) => ({ ...b, prijs_cent: prijzen.get(b.id) ?? 0 }));
} else if (bereik === 'tarieven') {
  // Bedragen uit de payload, tekst en structuur van schijf. De blokkenlijst
  // volgt de schijf: het tarievenscherm mag geen blokken toevoegen of van
  // volgorde wisselen.
  const nieuwePrijzen = new Map(schoneBlokken.map((b) => [b.id, b.prijs_cent]));
  uitBlokken = (Array.isArray(huidig.blokken) ? huidig.blokken : []).map((b) => ({
    ...b,
    prijs_cent: nieuwePrijzen.has(String(b.id))
      ? nieuwePrijzen.get(String(b.id))
      : Number(b.prijs_cent) || 0,
  }));
}

// $comment uit het bestaande bestand behouden: daar staat de waarschuwing in
// dat de voorbeeldteksten niet juridisch zijn nagekeken. Hij gaat als eerste
// sleutel het bestand in, zodat wie het bestand opent hem meteen leest.
const commentaar = huidig && huidig.$comment ? huidig.$comment : null;

const uit = {
  ...(commentaar ? { $comment: commentaar } : {}),
  soort,
  naam: bereik === 'tarieven' && huidig ? String(huidig.naam || naam) : naam,
  bespreeksjabloon:
    bereik === 'tarieven' && huidig
      ? (huidig.bespreeksjabloon ?? null)
      : (akte.bespreeksjabloon ? String(akte.bespreeksjabloon) : null),
  basistarief_cent: uitBasistarief,
  tarief_tweede_testament_cent: uitTariefTweede,
  verschotten: uitVerschotten,
  blokken: uitBlokken,
};

const bewaard = await bewaarVersie(soort);
fs.mkdirSync(AKTE_DIR, { recursive: true });
await writeFileAtomic(bestandVan(soort), JSON.stringify(uit, null, 2) + '\n');

// Niet blokkerend, wel het melden waard: een placeholder die nergens als veld
// staat blijft in de akte letterlijk als <<TYPFOUT>> staan.
const waarschuwingen = [];
for (const blok of (bereik === 'tarieven' ? [] : schoneBlokken)) {
  const gedeclareerd = new Set([
    ...blok.velden.map((v) => `<<${v.naam}>>`),
    ...SYSTEEM_PLACEHOLDERS,
  ]);
  const onbekend = [...new Set(placeholdersIn(blok.tekst))].filter((p) => !gedeclareerd.has(p));
  if (onbekend.length) {
    waarschuwingen.push(
      `Blok '${blok.naam}' gebruikt ${onbekend.join(', ')} zonder invulveld; ` +
      `die tekst komt letterlijk in de akte te staan.`
    );
  }
  const ongebruikt = blok.velden
    .map((v) => `<<${v.naam}>>`)
    .filter((p) => !placeholdersIn(blok.tekst).includes(p));
  if (ongebruikt.length) {
    waarschuwingen.push(
      `Blok '${blok.naam}' heeft invelden ${ongebruikt.join(', ')} die niet in de tekst voorkomen.`
    );
  }
}

return [{
  json: {
    success: true,
    actie: 'opslaan',
    soort,
    naam,
    nieuw: !bestaatAl,
    bereik,
    blokken_aantal: uit.blokken.length,
    vorige_versie_bewaard_als: bewaard,
    waarschuwingen,
  },
}];
